 out=[]
 for s in VARIABLES:
  r={k:"NOT_APPLICABLE" for k in FIELDS};r.update(source_row_or_group="ALL_RETAINED_ROWS",source_geometry="SOURCE_NATIVE_RETAINED",source_coffee_and_roast_scope="SOURCE_SPECIFIC",preparation_and_compaction_scope="SOURCE_SPECIFIC",uncertainty_semantics="AS_REPORTED_NO_INVENTED_CONFIDENCE",conversion_formula="IDENTITY_ONLY_WITHIN_IDENTICAL_SOURCE_QUANTITY",observation_operator_id="NONE",observation_operator_inputs="NONE",observation_operator_output="NONE",observation_operator_closure_status="NOT_REQUIRED",geometry_transfer_rule="EXPLICIT_EWP_FIXED_DOSE_OR_FIXED_GEOMETRY_DIAGNOSTIC",viscosity_treatment="NOT_APPLICABLE",required_assumptions="static source-conditioned sensitivity does not establish state equivalence",contextual_diagnostic_eligible="true",exclusion_reason="NONE" if s["primary_sensitivity_eligible"]=="true" else s["transfer_limitations"],claim_limit="SOURCE_CONDITIONED_SENSITIVITY_ONLY");r.update(s);out.append(r)
