  if r["mapping_class"]=="REQUIRES_OBSERVATION_OPERATOR" and r["primary_sensitivity_eligible"]=="true" and (r["observation_operator_closure_status"]!="CLOSED_FOR_SOURCE_CONDITIONED_SENSITIVITY" or "NONE" in (r["observation_operator_inputs"],r["observation_operator_output"])):raise ValueError("EWP_POROSITY_PERMEABILITY_PRIOR_001_UNCLOSED_OPERATOR_PRIMARY_ELIGIBILITY")
